const feedback = flow.get('sampleSequenceFeedback') || {};
const positions = Array.isArray(feedback.actual_positions) ? feedback.actual_positions : [];
const authority = feedback.command_authority || {};
if (positions.length < 4) { node.warn('Sample sequence requires at least four configured axes and current feedback'); return [null, { payload: 'Cannot start: four-axis feedback is not available' }]; }
if (authority.owned_by_this_client !== true) { node.warn('Request command authority before starting the sequence'); return [null, { payload: 'Cannot start: command authority is not owned' }]; }
if (flow.get('sampleSequenceRunning') === true) { return [null, { payload: 'Sequence is already running' }]; }
flow.set('sampleSequenceRunning', true);
flow.set('sampleSequenceStage', 'stage1');
msg.sequence_action = 'stage1';
msg.payload = { cmd: 'system/axes/move_abs', axes: [0, 2], positions: [300, 500], profile_velocities: [500, 1000] };
return [msg, { payload: 'Stage 1: moving Axis 0 to 300 @ 500 and Axis 2 to 500 @ 1000' }];

flow.set('sampleSequenceRunning', false);
flow.set('sampleSequenceStage', 'stopped');
msg.sequence_action = 'stop';
msg.payload = { cmd: 'system/axes/stop', axes: [0, 1, 2, 3] };
return [msg, { payload: 'Sequence stopped: controlled stop sent to Axes 0, 1, 2 and 3' }];

if (!flow.get('sampleSequenceRunning') || flow.get('sampleSequenceStage') !== 'stage1') return null;
const p = msg.payload?.actual_positions || [];
const v = msg.payload?.actual_velocities || [];
const complete = Math.abs(Number(p[0]) - 300) <= 0.5 && Math.abs(Number(v[0])) <= 1 && Math.abs(Number(p[2]) - 500) <= 0.5 && Math.abs(Number(v[2])) <= 1;
if (!complete) return null;
flow.set('sampleSequenceStage', 'stage2');
msg.sequence_action = 'stage2';
msg.payload = { cmd: 'system/axes/move_abs', axes: [1, 3], positions: [200, 400], profile_velocities: [400, 800] };
return [msg, { payload: 'Stage 2: moving Axis 1 to 200 @ 400 and Axis 3 to 400 @ 800' }];

if (!flow.get('sampleSequenceRunning') || flow.get('sampleSequenceStage') !== 'stage2') return null;
const p = msg.payload?.actual_positions || [];
const v = msg.payload?.actual_velocities || [];
const complete = Math.abs(Number(p[1]) - 200) <= 0.5 && Math.abs(Number(v[1])) <= 1 && Math.abs(Number(p[3]) - 400) <= 0.5 && Math.abs(Number(v[3])) <= 1;
if (!complete) return null;
flow.set('sampleSequenceStage', 'output');
msg.sequence_action = 'external_output';
msg.payload = { cmd: 'system/io/output_write', writes: [
  { io: 'io0', slot: 1, kind: 'digital', channel: 0, value: true },
  { io: 'io0', slot: 4, kind: 'analog', channel: 0, value: 1000 }
] };
return [msg, { payload: 'External action: DO io0/slot1/ch0 ON, AO io0/slot4/ch0 = 1000' }];

if (!flow.get('sampleSequenceRunning') || flow.get('sampleSequenceStage') !== 'wait_input') return null;
const devices = msg.payload?.io?.devices || [];
const device = devices.find(item => item.id === 'io0');
const modules = device?.modules || [];
const di = modules.find(item => Number(item.slot) === 2)?.inputs?.digital?.[0] === true;
const ai = Number(modules.find(item => Number(item.slot) === 4)?.inputs?.analog?.[0]);
if (!di || !Number.isFinite(ai) || ai < 500) return null;
flow.set('sampleSequenceStage', 'stage3');
msg.sequence_action = 'stage3';
msg.payload = { cmd: 'system/axes/move_abs', axes: [0, 1, 2], positions: [50, 100, 150], profile_velocities: [300, 400, 500] };
return [msg, { payload: 'Stage 3: DI is ON and AI >= 500; moving Axes 0, 1 and 2' }];

if (!flow.get('sampleSequenceRunning') || flow.get('sampleSequenceStage') !== 'stage3') return null;
const p = msg.payload?.actual_positions || [];
const v = msg.payload?.actual_velocities || [];
const targets = [[0, 50], [1, 100], [2, 150]];
const complete = targets.every(([axis, target]) => Math.abs(Number(p[axis]) - target) <= 0.5 && Math.abs(Number(v[axis])) <= 1);
if (!complete) return null;
flow.set('sampleSequenceStage', 'stage4');
msg.sequence_action = 'stage4';
msg.payload = { cmd: 'system/axis/move_abs', axis: 3, position: 250, profile_velocity: 600 };
return [msg, { payload: 'Stage 4: moving Axis 3 to 250 @ 600' }];

if (!flow.get('sampleSequenceRunning') || flow.get('sampleSequenceStage') !== 'stage4') return null;
const p = msg.payload?.actual_positions || [];
const v = msg.payload?.actual_velocities || [];
if (Math.abs(Number(p[3]) - 250) > 0.5 || Math.abs(Number(v[3])) > 1) return null;
flow.set('sampleSequenceRunning', false);
flow.set('sampleSequenceStage', 'complete');
return { payload: 'Sequence complete' };

const response = msg.payload || {};
if (response.result !== 'success') {
    flow.set('sampleSequenceRunning', false);
    flow.set('sampleSequenceStage', 'failed');
    const failure = response.failure || {};
    return { payload: `Sequence failed: ${failure.code || failure.message || 'command rejected'}` };
}
if (msg.sequence_action === 'external_output' && flow.get('sampleSequenceStage') === 'output') {
    flow.set('sampleSequenceStage', 'wait_input');
    return { payload: 'Waiting for DI io0/slot2/ch0 = ON and AI io0/slot4/ch0 >= 500' };
}
return null;

flow.set('sampleSequenceRunning', false);
flow.set('sampleSequenceStage', 'failed');
const error = msg.payload || {};
return { payload: `Sequence client error: ${error.code || error.message || 'unknown error'}` };
